// The entries above whose tags no longer appear in BANKS (MC-HIST-01 to
// -13, MC-CRIM-01, MC-LAW-02) come from History and Criminology banks that
// were replaced. They are kept for the same reason MC_LABELS keeps retired
// tags: rows in the `responses` table still reference them, so a teacher
// looking at last year's data should still get the starter, not a bare code.

// ---- Structured fallback builders ---------------------------------------
// These builders are intentionally small. They use the live question and
// scaffold so a low-use tag still gets a useful, misconception-specific task
// without adding hundreds of near-identical literal entries.
function _mcStarterQuestion(tag) {
  if (typeof BANKS === 'undefined') return null;
  for (var bankId in BANKS) {
    var questions = BANKS[bankId] && BANKS[bankId].questions || [];
    for (var i = 0; i < questions.length; i++) {
      var questionTags = Array.isArray(questions[i].tag) ? questions[i].tag : [questions[i].tag];
      if (questionTags.indexOf(tag) !== -1) return questions[i];
    }
  }
  return null;
}

function _mcStarterHash(value) {
  var hash = 0;
  var text = String(value || '');
  for (var i = 0; i < text.length; i++) hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  return hash;
}

function _mcStarterText(question) {
  return question ? String(question.stem || '').replace(/\s+/g, ' ').trim() : '';
}

function _mcStarterScaffold(question) {
  return question ? String(question.scaffold || '').replace(/\s+/g, ' ').trim() : '';
}

function _mcStarterInfer(question) {
  var text = (_mcStarterText(question) + ' ' + _mcStarterScaffold(question)).toLowerCase();
  if (/\b(what is meant by|what does .* mean|what is the main role|which structure|which memory store|which feature|which term)\b/.test(text)) return 'distinguish';
  if (/\b(calculate|work out|compute|formula|equation|gradient|percentage|probability|ratio|mean|magnification|velocity|force|energy|power|resistance|rate of change|break-even|profit|revenue|elasticity)\b|\b\d+\s*[×x÷%]/.test(text)) return 'calculate';
  if (/\b(draw|sketch|plot|graph|diagram|axis|axes|curve|wave|ray|field|circuit|histogram|scatter)\b/.test(text)) return /\b(graph|plot|axis|axes|histogram|scatter)\b/.test(text) ? 'graph' : 'diagram';
  if (/\b(sequence|order|stages|step-by-step|process|chain|cycle|pathway|transmission|replication|algorithm)\b/.test(text)) return 'sequence';
  if (/\b(compare|difference|versus|\bvs\.?\b|both|whereas|similarit|contrast)\b/.test(text)) return 'compare';
  if (/\b(classif|sort|match|categor|which (?:term|type|category)|label each|distinguish)\b/.test(text)) return /\b(distinguish|difference|vs\.?|compare)\b/.test(text) ? 'distinguish' : 'classify';
  if (/\b(rewrite|correct|error|incorrect|wrong|fix|claim|statement|student (?:wrote|thinks|says))\b/.test(text)) return /\b(rewrite|sentence|statement)\b/.test(text) ? 'rewrite' : 'correct';
  if (/\b(scenario|case study|example|apply|application|situation|patient|company|business|experiment|new context)\b/.test(text)) return 'apply';
  return 'evaluate';
}

function _mcStarterTitle(type, name, variant) {
  var titles = {
    calculate: ['Work the misconception', 'Number check', 'Show the method'],
    classify: ['Sort it before you explain it', 'Category check', 'Put the terms in their place'],
    distinguish: ['Draw the boundary', 'Two ideas, one decision', 'Which one is it?'],
    correct: ['Repair the claim', 'Find the faulty step', 'Make the answer defensible'],
    rewrite: ['Rewrite for accuracy', 'Upgrade the answer', 'Words that earn the mark'],
    sequence: ['Build the chain', 'Put the process in motion', 'What happens next?'],
    compare: ['Side-by-side check', 'Compare the pair', 'Same or different?'],
    diagram: ['Make the model visible', 'Draw what the words mean', 'Diagram check'],
    graph: ['Read it from the axes', 'Graph the relationship', 'Plot before you predict'],
    apply: ['Use the rule in context', 'Transfer check', 'New situation, same idea'],
    evaluate: ['Commit, then qualify', 'Decide and defend', 'The judgement test']
  };
  var choices = titles[type] || titles.evaluate;
  return choices[variant % choices.length] + (name ? ': ' + name : '');
}

function _mcStarterFallback(tag, label, question) {
  var name = label || (typeof resolveMCLabel === 'function' ? resolveMCLabel(tag) : '') || tag;
  var stem = _mcStarterText(question) || ('the question tagged ' + tag);
  var scaffold = _mcStarterScaffold(question);
  var type = _mcStarterInfer(question);
  var variant = _mcStarterHash(tag);
  var lead = [
    'Commit silently before anyone explains: write your answer and one reason.',
    'Everyone writes first; discussion starts only after every board has an answer.',
    'Choose an answer, then underline the exact word or step that decided it.'
  ][variant % 3];
  var follow = [
    'Teacher move: take one wrong answer, ask which word in the scaffold disproves it, then run the same check on a fresh example.',
    'Teacher move: reveal the governing rule only after the vote; ask one student to repair the most plausible wrong answer aloud.',
    'Teacher move: collect the two most common answers, compare their reasoning, and finish with a one-question recheck.'
  ][variant % 3];
  var task;
  if (type === 'calculate') task = 'Calculate or derive the answer to this question: “' + stem + '” Show the first substitution or operation, then circle the final value and its unit or meaning.';
  else if (type === 'classify' || type === 'distinguish') task = 'Make the decision demanded by this question: “' + stem + '” Write the category or term first, then give one boundary rule that separates it from the nearest alternative.';
  else if (type === 'correct' || type === 'rewrite') task = 'Answer this question: “' + stem + '” Then write the tempting wrong version you would expect from this misconception and cross out the precise part that fails.';
  else if (type === 'sequence') task = 'Turn this question into a four-step chain: “' + stem + '” Number the steps, commit to the order, and add the cause or mechanism on each arrow.';
  else if (type === 'compare') task = 'Answer this comparison question: “' + stem + '” Complete two columns: what is true of each idea, and the single feature that keeps them from being interchangeable.';
  else if (type === 'diagram' || type === 'graph') task = 'Answer this visual question: “' + stem + '” Draw or annotate the model before the reveal; label the feature that would change if the common misconception were true.';
  else if (type === 'apply') task = 'Apply the idea to this question: “' + stem + '” State your decision, cite the rule, and predict what would happen if one important condition changed.';
  else task = 'Take a position on this question: “' + stem + '” Give one piece of evidence, one condition that limits it, and a one-sentence judgement.';
  return {type:type, title:_mcStarterTitle(type, name, variant), instruction:lead + ' ' + task + ' ' + follow, prompt:scaffold ? 'Scaffold to revisit after the vote: ' + scaffold : 'After the vote, return to the question wording and identify the clue that supports the answer.'};
}

function _mcCuratedSubject(tag) {
  var groups = [MC_CURATED_TAGS, MC_ADDITIONAL_TAGS];
  for (var g = 0; g < groups.length; g++) for (var subject in groups[g]) {
    if (groups[g][subject].indexOf(tag) !== -1) return subject;
  }
  return '';
}

function _mcCuratedStarter(tag, label, question) {
  var base = _mcStarterFallback(tag, label, question);
  var stem = _mcStarterText(question) || ('the question tagged ' + tag);
  var anchor = {
    calculate:'Students commit to a worked answer, show the first operation, and annotate why the most tempting alternative fails.',
    diagram:'Students commit to a labelled sketch before seeing the model answer, then correct one misplaced label or relationship.',
    graph:'Students commit to the shape and direction of the graph, label both axes, and explain one feature the common error would reverse.',
    sequence:'Students commit to the order of the process, write the mechanism on each arrow, and identify the first step that would make the error inevitable.',
    compare:'Students commit to a two-column comparison, then write one sentence explaining why the paired ideas cannot be swapped.',
    classify:'Students commit to a category for each case, then write the rule that separates the correct category from its nearest distractor.',
    distinguish:'Students commit to the distinction, then give a boundary example that would be misclassified by the common misconception.',
    correct:'Students commit to a correction, then underline the exact word or causal link that makes the original claim wrong.',
    rewrite:'Students commit to a rewritten answer, then mark the added term or qualification that earns the correction mark.',
    apply:'Students commit to a decision in the context, cite the governing rule, and predict what changes when one condition is removed.',
    evaluate:'Students commit to a judgement, support it with one precise concept, and state the condition under which the judgement would change.'
  }[base.type] || 'Students commit to an answer before the reveal, then identify the precise rule that separates it from the common wrong answer.';
  base.title = base.title.replace(/^([^:]+): /, '');
  var opening = [
    'Commit before the reveal: answer this exact question — “' + stem + '” ',
    'Start with a silent answer to “' + stem + '” ',
    'Put one answer on the board for “' + stem + '” before discussion. '
  ][_mcStarterHash(tag) % 3];
  base.instruction = opening + anchor + ' Teacher move: reveal the scaffold only after every student has committed; take the strongest wrong answer and repair the precise step that caused it.';
  return base;
}

function getStarterActivity(tag, label) {
  if (tag && MC_STARTERS[tag]) return MC_STARTERS[tag];
  if (tag && _mcCuratedSubject(tag)) return _mcCuratedStarter(tag, label, _mcStarterQuestion(tag));
  return _mcStarterFallback(tag, label, _mcStarterQuestion(tag));
}

if (typeof window !== 'undefined') {
  window.MC_STARTERS = MC_STARTERS;
  window.getStarterActivity = getStarterActivity;
}
